    EquateRange = class extends XFAObject {
      constructor(attributes) {
        super(CONFIG_NS_ID, "equateRange");
        this.from = attributes.from || "";
        this.to = attributes.to || "";
        this._unicodeRange = attributes.unicodeRange || "";
      }
      get unicodeRange() {
        const ranges = [];
        const unicodeRegex = /U\+([0-9a-fA-F]+)/;
        const unicodeRange = this._unicodeRange;
        for (let range2 of unicodeRange.split(",").map((x) => x.trim()).filter((x) => !!x)) {
          range2 = range2.split("-", 2).map((x) => {
            const found = x.match(unicodeRegex);
            if (!found) {
              return 0;
            }
            return parseInt(found[1], 16);
          });
          if (range2.length === 1) {
            range2.push(range2[0]);
          }
          ranges.push(range2);
        }
        return shadow2(this, "unicodeRange", ranges);
      }
    };
